SELECT COUNT(*) FROM users as u, comments as c, posts as p, postHistory as ph WHERE c.PostId = p.Id AND u.Id= c.UserId AND ph.PostId = p.Id AND u.Reputation>=1 AND u.Reputation<=491 AND u.DownVotes>=0 AND u.DownVotes<=0 AND c.CreationDate>=CAST('2010-07-11 12:25:05' AS TIMESTAMP) AND c.CreationDate<=CAST('2014-09-11 13:43:09' AS TIMESTAMP) AND p.CommentCount>=0 AND p.CommentCount<=14 AND ph.CreationDate>=CAST('2010-08-06 03:14:53' AS TIMESTAMP)
